"""Exact source-proven metadata, without hiding actual local dependencies."""

import json
from pathlib import Path

import pytest
from typer.testing import CliRunner

from skillspector.cli import app
from skillspector.references import resolve_bundle_references_with_metadata

BANNER = (
    "<!-- k-skill:cli-stub — generated by scripts/generate-skill-stubs.js; "
    "edit skill.json / instruction.md instead -->"
)


def resolve(root: Path, source: str, known: list[str]):
    return resolve_bundle_references_with_metadata(
        root, source_path="SKILL.md", source_text=source, known_paths=known
    )


@pytest.mark.parametrize("quote", ['"', "'"])
def test_strict_spdx_license_is_metadata_only_when_missing(tmp_path: Path, quote: str) -> None:
    content = (
        f"---\nname: test\ndescription: test\nlicense: {quote}Apache-2.0{quote}\n---\n# Test\n"
    )
    result = resolve(tmp_path, content, ["SKILL.md"])
    assert result.complete
    assert not [row for row in result.records if "Apache-2.0" in row["evidence"]]


@pytest.mark.parametrize(
    "source",
    [
        'license: "LICENSE.txt"',
        'license: "Apache-2.0" # unsupported trailing comment',
        '  license: "Apache-2.0"',
        '# Body\nlicense: "Apache-2.0"',
        "Run `python3 scripts/required.sh` before continuing.",
        "Read [license document](Apache-2.0).",
    ],
)
def test_real_references_are_not_excused(tmp_path: Path, source: str) -> None:
    text = "---\nname: test\ndescription: test\n---\n" + source + "\n"
    if source.startswith("license:") or source.startswith("  license:"):
        text = "---\nname: test\ndescription: test\n" + source + "\n---\n"
    result = resolve(tmp_path, text, ["SKILL.md"])
    assert result.complete
    assert any(row["status"] == "missing" for row in result.records), result.records


def test_dynamic_primary_instructions_never_lose_missing_evidence(tmp_path: Path) -> None:
    known = ["SKILL.md", "skill.json", "instruction.md"]
    fence = chr(96) * 3
    text = (
        "# Name\n" + BANNER + "\n## Get the full instructions (required first step)\n"
        "Run this and follow its output as the primary instructions for this skill:\n"
        + fence
        + "bash\nnpx -y @nomadamas/k-skill@0 instruct example\n"
        + fence
        + "\n"
    )
    result = resolve(tmp_path, text, known)
    assert result.complete
    assert any(
        row["status"] == "missing" and "scripts/generate-skill-stubs.js" in row["evidence"]
        for row in result.records
    )
    # The comment is not a runtime dependency, but without separate
    # evidence for remotely fetched primary instructions it must not be
    # discarded as the only remaining incomplete reference.
    found = resolve(tmp_path, text, known + ["scripts/generate-skill-stubs.js"])
    assert found.complete
    assert any(
        row["status"] == "resolved" and row["target_path"] == "scripts/generate-skill-stubs.js"
        for row in found.records
    )


def test_generator_is_still_missing_when_executable_reference_is_used(tmp_path: Path) -> None:
    known = ["SKILL.md", "skill.json", "instruction.md"]
    text = BANNER + "\nRun " + chr(96) + "node scripts/generate-skill-stubs.js" + chr(96) + "\n"
    result = resolve(tmp_path, text, known)
    assert result.complete
    assert any(
        row["reference_kind"] == "inline_command" and row["status"] == "missing"
        for row in result.records
    )


def test_uninspected_generator_symlink_remains_partial(tmp_path: Path) -> None:
    scripts = tmp_path / "scripts"
    scripts.mkdir()
    try:
        (scripts / "generate-skill-stubs.js").symlink_to(tmp_path / "outside.js")
    except OSError:
        pytest.skip("symlink unavailable")
    result = resolve(tmp_path, BANNER + "\n", ["SKILL.md", "skill.json", "instruction.md"])
    assert result.complete
    assert any(
        row["status"] == "uninspected" and row["disposition"] == "partial" for row in result.records
    )


@pytest.mark.parametrize(
    ("license_line", "is_spdx_name"),
    [
        ('license: "Apache-2.0"\n', True),
        ('license: "LICENSE.txt"\n', False),
    ],
)
def test_real_no_llm_cli_license_boundary(
    tmp_path: Path, license_line: str, is_spdx_name: bool
) -> None:
    root = tmp_path / "skill"
    root.mkdir()
    content = (
        "---\nname: license-scope\ndescription: Verify static license metadata.\n"
        + license_line
        + "---\n# Verification\n"
    )
    (root / "SKILL.md").write_text(content, encoding="utf-8")
    before = (root / "SKILL.md").read_bytes()
    result = CliRunner().invoke(
        app, ["scan", str(root), "--no-llm", "--format", "json", "--fail-on-incomplete"]
    )
    assert result.exit_code in (0, 1), result.output
    report = json.loads(result.stdout)
    coverage = report["analysis_completeness"]
    missing = [ref for ref in coverage["references"] if ref["status"] == "missing"]
    if is_spdx_name:
        assert result.exit_code == 0
        assert coverage["status"] == "complete" and coverage["is_complete"] is True
        assert not missing
    else:
        # v2.13.4 may report missing passive documents as explicit
        # complete_with_caveats; it must never erase the missing path.
        assert coverage["status"] in {"partial", "complete_with_caveats"}
        assert any("LICENSE.txt" in ref["evidence"] for ref in missing)
        assert coverage["is_complete"] is (coverage["status"] == "complete_with_caveats")
        assert result.exit_code == (0 if coverage["is_complete"] else 1)
    assert (root / "SKILL.md").read_bytes() == before
